INSERT INTO products (id, name, category, specs, price, oldPrice, img, description, created_at) VALUES
(1, 'طقم فن الريزن كامل مع قوالب', 'فن الريزن', 'ريزن شفاف · قوالب متنوعة · ألوان', 450.00, 550.00, '/uploads/product-1789049996414.png', 'طقم احترافي كامل لصناعة قطع الريزن الفنية في المنزل، يشمل ريزن شفاف وألوان وقوالب متنوعة.', '2026-09-10 14:17:51'),(2, 'ديكور ريزن مطلي بالذهب', 'فن الريزن', 'مطلي بالذهب · مقاس 20 سم', 300.00, NULL, 'https://picsum.photos/seed/resin2/600/700', 'قطعة ديكور فنية من الريزن المصبوب يدوياً مع لمسات ذهبية أنيقة.', '2026-09-10 14:17:51'),(3, 'بوكيه ورد مجفف جيبسي', 'تجفيف الورود', 'ورد مجفف طبيعي · لون بيج · ارتفاع 30 سم', 180.00, 220.00, 'https://picsum.photos/seed/dried1/600/700', 'بوكيه ورد مجفف طبيعي بألوان هادئة يصلح لتزيين المنزل والمكتب.', '2026-09-10 14:17:51'),(4, 'فرز ورد مجفف ملون', 'تجفيف الورود', 'توليفة ملونة · 12 زهرة', 150.00, NULL, 'https://picsum.photos/seed/dried2/600/700', 'فرز ورد مجفف ملون جاهز للتنسيق في المزهريات يدوم لسنوات.', '2026-09-10 14:17:51'),(5, 'كتاب قهوة ملكي للكتابة', 'كتب الكتاب', 'غلاف جلد فاخر · ذهبي', 500.00, 650.00, 'https://picsum.photos/seed/wed1/600/700', 'كتاب كتاب (إكسسوارات الزفاف) بغلاف جلد فاخر ونقوش ذهبية ملكية لتدوين أسماء المدعوين.', '2026-09-10 14:17:51'),(6, 'كتاب كتاب وردي فاتح', 'كتب الكتاب', 'وردي فاتح · نقوش ناعمة', 380.00, NULL, 'https://picsum.photos/seed/wed2/600/700', 'كتاب أنيق لتسجيل حضور العرس بتصميم وردي فاتح يليق بالأفراح.', '2026-09-10 14:17:51'),(7, 'صينية شبكة مزخرفة', 'صواني الشبكة', 'معدن · لون ذهبي · مقاس 30 سم', 120.00, 150.00, 'https://picsum.photos/seed/tray1/600/700', 'صينية شبكة أنيقة بتصميم مزخرف ذهبي تصلح لعرض الحلويات والهدايا.', '2026-09-10 14:17:51'),(8, 'صينية شبكة دائرية', 'صواني الشبكة', 'دائرية · قطر 25 سم', 95.00, NULL, 'https://picsum.photos/seed/tray2/600/700', 'صينية شبكة دائرية بسعر اقتصادي مثالية للتقديم والعرض.', '2026-09-10 14:17:51'),(9, 'تربيزة طارة خطوبة كاملة', 'طارات الخطوبة', 'طارة + برواز + ورود صناعية', 900.00, 1200.00, 'https://picsum.photos/seed/eng1/600/700', 'تربيزة كاملة لطارة الخطوبة تشمل الإعداد الجاهز للتصوير بأجواء رومانسية.', '2026-09-10 14:17:51'),(10, 'طارة خطوبة ورد صناعي', 'طارات الخطوبة', 'ورود صناعية بيضاء وذهبية', 250.00, NULL, 'https://picsum.photos/seed/eng2/600/700', 'طارة خطوبة مزينة بورود صناعية فاخرة جاهزة لليلة الخطوبة.', '2026-09-10 14:17:51'),(11, 'تربيزة سبوع بيبي كاملة', 'سبوع البيبي', 'تشمل المنضدة والديكورات', 850.00, 1100.00, 'https://picsum.photos/seed/baby1/600/700', 'تجهيزات سبوع البيبي كاملة بألوان لطيفة تناسب استقبال المولود الجديد.', '2026-09-10 14:17:51'),(12, 'بوكيه سبوع بيبي ورد', 'سبوع البيبي', 'ورد طبيعي + بالونات صغيرة', 240.00, NULL, 'https://picsum.photos/seed/baby2/600/700', 'بوكيه سبوع جاهز بألوان هادئة يضفي بهجة على حفل استقبال البيبي.', '2026-09-10 14:17:51'),(13, 'مج حراري قابل للطباعة', 'مجات طباعة و ديجيتال حراري', 'سيراميك · أبيض · 350 مل', 60.00, NULL, 'https://picsum.photos/seed/mug1/600/700', 'مج أبيض جاهز للطباعة الحرارية بأي صورة أو تصميم تختاره.', '2026-09-10 14:17:51'),(14, 'مج ديجيتال حراري مع ملعقة', 'مجات طباعة و ديجيتال حراري', 'مع ملعقة وغطاء · أسود', 120.00, 160.00, 'https://picsum.photos/seed/mug2/600/700', 'هدية مثالية كاملة مع ملعقة وغطاء، يمكن طباعة الصور عليه حرارياً.', '2026-09-10 14:17:51'),(15, 'بوكيه تخرج ورد + دبدوب', 'التخرج', 'ورد + دبدوب صغير · كريمي', 320.00, NULL, 'https://picsum.photos/seed/grad1/600/700', 'بوكيه تخرج مميز يجمع بين الورد والدبدوب لتهنئة الخريجين.', '2026-09-10 14:17:51'),(16, 'بوكيه تخرج بالجواييش', 'التخرج', 'جواييش + ورود صناعية', 350.00, 420.00, 'https://picsum.photos/seed/grad2/600/700', 'بوكيه تخرج احتفالي مزين بالجواييش لعرضها في يوم التخرج.', '2026-09-10 14:17:51'),(17, 'بوكيه ورد طبيعي مشكل', 'بوكيهات', 'ورد طبيعي · توليفة مشكلة', 280.00, NULL, 'https://picsum.photos/seed/bq1/600/700', 'بوكيه ورد طبيعي مشكل بألوان مبهجة يناسب الهدايا والمناسبات السعيدة.', '2026-09-10 14:17:51'),(18, 'بوكيه ورد أحمر كلاسيك', 'بوكيهات', 'ورد أحمر طبيعي · ورود 12', 350.00, 400.00, 'https://picsum.photos/seed/bq2/600/700', 'بوكيه ورد أحمر كلاسيكي مثالي للتعبير عن الحب في المناسبات.', '2026-09-10 14:17:51'),(19, 'بوكيه ورد أبيض مع أنثروريوم', 'بوكيهات', 'أبيض فاخر · أنثروريوم أحمر', 450.00, NULL, 'https://picsum.photos/seed/bq3/600/700', 'لوكيه أنيق من الورد الأبيض مع لمسات أنثروريوم حمراء جريئة.', '2026-09-10 14:17:51');

